import sortBy from 'lodash/sortBy'
import {useContext, useMemo} from 'react'
import {graphql, useFragment} from 'react-relay'

import {usePipelineId} from '../../../../pages/PipelinesPages/hooks/pipeline'

import type {PipelinesSidebarFragment$key} from './__generated__/PipelinesSidebarFragment.graphql'
import {PipelinesSidebarSearchContext} from './PipelinesSidebar.contexts'
import type {PipelinesSidebarItemType, PipelinesSidebarPipeline} from './PipelinesSidebar.types'

const pipelinesFragment = graphql`
  fragment PipelinesSidebarFragment on Pipelines {
    pipeline {
      name
      id
    }
  }
`

export function usePipelinesSidebarItems(
  pipelinesKey: PipelinesSidebarFragment$key | null,
): [PipelinesSidebarItemType[], number] {
  const activePipelineId = usePipelineId()
  const pipelines = useFragment(pipelinesFragment, pipelinesKey)?.pipeline
  const searchQuery = useContext(PipelinesSidebarSearchContext).searchQuery

  const sortedPipelines = useMemo(() => sortBy(pipelines, ({name}) => name), [pipelines])

  return useMemo(() => {
    let activeItemIndex = -1
    const items: PipelinesSidebarItemType[] = []

    sortedPipelines?.forEach((pipeline, i) => {
      if (
        searchQuery != null &&
        !pipeline?.name?.toLowerCase().includes(searchQuery.toLowerCase())
      ) {
        return
      }
      const active = activePipelineId === pipeline.id

      items.push({
        type: 'pipelines-sidebar-pipeline',
        id: pipeline.id,
        pipelineId: pipeline.id,
        title: pipeline?.name ?? 'Unknown pipeline',
        level: 0,
        active,
      } as PipelinesSidebarPipeline)

      if (active) {
        activeItemIndex = i
      }
    })

    return [items, activeItemIndex]
  }, [activePipelineId, sortedPipelines, searchQuery])
}
