import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import cn from 'classnames'
import {memo, useContext, useMemo} from 'react'
import type * as React from 'react'

import {useAppSelector} from '../../../../../../../../hooks/react-redux'
import {useQueryParams} from '../../../../../../../../hooks/routes'
import {getStatusKey} from '../../../../../../../../rest/schemata'
import {getPipelineHref, isPipelinesEditScreen} from '../../../../../../../../routes'
import {getStatuses} from '../../../../../../../../selectors'
import type {PipelineId, ProjectOrBuildTypeStatus} from '../../../../../../../../types'
import {getPipelineStatusRequest} from '../../../../../../../../types'
import MatchingTitle from '../../../../../../../common/MatchingItem/MatchingItem'
import StatusUpdater from '../../../../../../../common/ProjectsTree/ProjectsTreeItem/StatusUpdater/StatusUpdater'
import SidebarLink from '../../../../../../../common/Sidebar/SidebarLink/SidebarLink'
import {PipelinesSidebarSearchContext} from '../../../PipelinesSidebar.contexts'

import styles from './PipelinesSidebarPipelineItem.module.css'

type Props = {
  id: string
  pipelineId: PipelineId
  title: string
  ellipsisRef?: React.Ref<HTMLDivElement>
  isTooltip?: boolean
}

function PipelinesSidebarPipelineItem({pipelineId, title, ellipsisRef, isTooltip = false}: Props) {
  const searchQuery = useContext(PipelinesSidebarSearchContext).searchQuery

  const statuses = useAppSelector(getStatuses)

  const statusRequest = getPipelineStatusRequest(pipelineId)
  const statusKey = statusRequest ? getStatusKey(statusRequest) : null
  const statusInfo: ProjectOrBuildTypeStatus | null | undefined =
    statuses && statusKey ? statuses[statusKey] : null

  const systemProblems = statusInfo?.systemProblems
  const runningCount = statusInfo?.running ?? 0
  const queuedCount = statusInfo?.queued ?? 0

  const queryParams = useQueryParams()
  const isEditingPipelines = isPipelinesEditScreen(queryParams)

  const to = useMemo(
    () => ({
      pathname: getPipelineHref(pipelineId),
      search: isEditingPipelines ? `edit=${isEditingPipelines}` : '',
    }),
    [pipelineId, isEditingPipelines],
  )

  return (
    <SidebarLink
      to={to}
      className={cn(styles.link, {[styles.offset]: !isTooltip})}
      ellipsisRef={ellipsisRef}
      tailClassName={styles.tail}
      tail={
        <div className={styles.tail}>
          {runningCount > 0 ? (
            <span
              className={styles.counter}
              title={`${runningCount} running build${runningCount > 1 ? 's' : ''}`}
            >
              <SvgIcon icon="spinner-static" className={styles.counterIcon} />
              <span className={styles.counterText}>{runningCount}</span>
            </span>
          ) : null}
          {queuedCount > 0 ? (
            <span
              className={styles.counter}
              title={`${queuedCount} queued build${queuedCount > 1 ? 's' : ''}`}
            >
              <SvgIcon icon="hourglass" className={styles.counterIcon} />
              <span className={styles.counterText}>{queuedCount}</span>
            </span>
          ) : null}
          {systemProblems != null && systemProblems.length > 0 && (
            <SvgIcon
              icon="warning"
              className={styles.warningIcon}
              title={systemProblems[0].title}
            />
          )}
        </div>
      }
    >
      <StatusUpdater
        pipelineId={pipelineId}
        subscribeDelayMS={1000}
        updateOverviewParents
        withoutBranch
      />
      <MatchingTitle searchQuery={searchQuery}>{title}</MatchingTitle>
    </SidebarLink>
  )
}

export default memo(PipelinesSidebarPipelineItem)
