import type {EntryPointProps} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'
import type {ScrollParams} from 'react-virtualized/dist/es/Grid'

import SidebarPanelContentNoResults from '../../SidebarPanelContentNoResults/SidebarPanelContentNoResults'
import {usePipelinesSidebarItems} from '../PipelinesSidebar.hooks'

import type {PipelinesSidebarContentQuery} from './__generated__/PipelinesSidebarContentQuery.graphql'
import {query} from './PipelinesSidebarContent.queries'
import PipelinesSidebarItems from './PipelinesSidebarItems/PipelinesSidebarItems'

import styles from './PipelinesSidebarContent.module.css'

type Queries = {
  main: PipelinesSidebarContentQuery
}

type Props = {
  onScroll: (params: ScrollParams) => void
}

function PipelinesSidebarContent({queries, props}: EntryPointProps<Queries, {}, Props, {}>) {
  const {pipelinesRest = null} = usePreloadedQuery(query, queries.main)
  const [items, activeItemIndex] = usePipelinesSidebarItems(pipelinesRest)

  if (items.length === 0) {
    return <SidebarPanelContentNoResults />
  }
  return (
    <PipelinesSidebarItems
      className={styles.tree}
      items={items}
      activeItemIndex={activeItemIndex}
      onScroll={props.onScroll}
    />
  )
}
export type PipelinesSidebarContentComponent = typeof PipelinesSidebarContent
export default PipelinesSidebarContent
