import {memo} from 'react'
import type {ScrollParams} from 'react-virtualized/dist/es/Grid'

import {stringifyId} from '../../../../../../../types'
import VirtualizedTree from '../../../../../../common/VirtualizedTree/VirtualizedTree'
import type {VirtualizedTreeChildProps} from '../../../../../../common/VirtualizedTree/VirtualizedTree'
import type {PipelinesSidebarItemType} from '../../PipelinesSidebar.types'

import PipelinesSidebarItem from './PipelinesSidebarItem/PipelinesSidebarItem'

type Props = {
  className?: string
  items: ReadonlyArray<PipelinesSidebarItemType>
  activeItemIndex: number
  onScroll?: (params: ScrollParams) => void
}

const renderItem = (props: VirtualizedTreeChildProps<PipelinesSidebarItemType>) => (
  <PipelinesSidebarItem key={`${props.item.type}-${stringifyId(props.item.id)}`} {...props} />
)

function PipelinesSidebarItems({items, className, activeItemIndex, onScroll}: Props) {
  return (
    <VirtualizedTree
      ariaLabel="Pipelines"
      className={className}
      flatItems={items}
      itemHeight={24}
      firstLevelIndent={0}
      levelIndent={18}
      scrollToIndex={activeItemIndex}
      onScroll={onScroll}
    >
      {renderItem}
    </VirtualizedTree>
  )
}

export default memo(PipelinesSidebarItems)
